<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const adminName = ref('Admin')
onMounted(async () => {
    try {
        const response = await fetch('http://127.0.0.1:5000/api/admin/profile', { credentials: 'include' })
        if (response.ok) adminName.value = (await response.json()).data.username
    } catch { /* Keep the default greeting if the request fails. */ }
})
const logoutError = ref('')
const isLoggingOut = ref(false)

async function handleLogout() {

    isLoggingOut.value = true

    try{

        const response = await fetch('http://127.0.0.1:5000/api/logout',

        {method: 'POST', credentials:'include'}
    )

        if (!response.ok) {
            throw new Error('Logout failed')
        }
        await router.replace('/login')

    }catch (error) {
         logoutError.value = error || 'Unable to logout'
    } finally {
        isLoggingOut.value = false
    }

}
</script>

